namespace scratchbird::engine::internal_api { namespace {
using Descriptor=scratchbird::engine::sblr::SblrResultSetPassDescriptorV1;
std::mutex mutex_; std::unordered_map<std::string,Descriptor> live,used; std::uint64_t generation=0;
EngineApiDiagnostic D(std::string code,std::string key){return MakeEngineApiDiagnostic(std::move(code),std::move(key),{});}
bool tagged(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();}
scratchbird::engine::sblr::PassUuid uuid(){scratchbird::engine::sblr::PassUuid out{};auto value=scratchbird::core::uuid::GenerateEngineIdentityV7(scratchbird::core::platform::UuidKind::object,static_cast<std::uint64_t>(std::chrono::system_clock::now().time_since_epoch().count())+(++generation));if(value.ok())std::copy(value.value.value.bytes.begin(),value.value.value.bytes.end(),out.begin());return out;}
std::string key(const auto&u){static constexpr char hex[]="0123456789abcdef";std::string s;for(auto b:u){s.push_back(hex[b>>4]);s.push_back(hex[b&15]);}return s;}
bool journal(const EngineRequestContext&c,char event,const Descriptor&d){std::ofstream f(c.database_path+".sb.sblr_result_set_pass.v1",std::ios::app);if(!f)return false;f<<event<<'\t'<<key(d.descriptor)<<'\t'<<d.descriptor_generation<<'\n';f.flush();return bool(f);}
}
SblrResultSetPassCoordinationResult CompileSblrResultSetPassDescriptor(const EngineRequestContext&c,const EngineUuid&receipt,std::uint64_t occurrence,std::uint32_t pass_occurrence,std::uint64_t availability){std::lock_guard lock(mutex_);SblrResultSetPassCoordinationResult r;if(!tagged(c,"private_result_set_pass_compiler")||!c.statement_metadata_snapshot_engine_owned){r.diagnostic=D("SECURITY.ACCESS_DENIED","sblr.result_set_pass.descriptor_hidden");return r;}if(!scratchbird::core::uuid::IsEngineIdentityUuid(receipt) || receipt != c.statement_uuid||!occurrence||!pass_occurrence||!availability){r.diagnostic=D("SBLR.OPERAND_INVALID","sblr.result_set_pass.coordination_invalid");return r;}auto&d=r.descriptor;d.descriptor=uuid();d.source_handle=uuid();d.row_shape=uuid();d.security=uuid();d.mga=uuid();d.recipient_session=uuid();d.owner_session=c.session_uuid.bytes;d.owner_transaction=c.transaction_uuid.bytes;d.descriptor_generation=d.source_generation=d.row_shape_generation=d.security_generation=d.mga_generation=++generation;d.owner_local_transaction_id=c.local_transaction_id;d.lifetime=1;d.transfer_mode=1;d.source_state=1;d.expiry_monotonic_ns=static_cast<std::uint64_t>(std::chrono::steady_clock::now().time_since_epoch().count())+60000000000ULL;d.maximum_consumers=1;d.source_evidence[0]=1;d.availability_generation=availability;auto bytes=scratchbird::engine::sblr::EncodeSblrResultSetPassDescriptorV1(d,false);if(bytes.size()!=288||!scratchbird::engine::sblr::DecodeSblrResultSetPassDescriptorV1(bytes.data(),bytes.size(),&d,nullptr,false)||!journal(c,'P',d)){r.diagnostic=D("RESULT_SET.PASS_FAILED","sblr.result_set_pass.publish_failed");return r;}live[key(d.descriptor)]=d;r.ok=true;r.diagnostic=D("OK","ok");return r;}
SblrResultSetPassCoordinationResult ConsumeSblrResultSetPassDescriptor(const EngineRequestContext&c,const Descriptor&d){std::lock_guard lock(mutex_);SblrResultSetPassCoordinationResult r;if(!tagged(c,"private_result_set_pass")){r.diagnostic=D("SECURITY.ACCESS_DENIED","sblr.result_set_pass.descriptor_hidden");return r;}const auto k=key(d.descriptor);auto it=live.find(k);if(it==live.end()){r.diagnostic=used.count(k)?D("RESULT_SET.STALE","sblr.result_set_pass.stale"):D("SECURITY.ACCESS_DENIED","sblr.result_set_pass.descriptor_hidden");return r;}if(scratchbird::engine::sblr::EncodeSblrResultSetPassDescriptorV1(it->second,true)!=scratchbird::engine::sblr::EncodeSblrResultSetPassDescriptorV1(d,true)){r.diagnostic=D("RESULT_SET.STALE","sblr.result_set_pass.stale");return r;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){r.diagnostic=D("PROCESS.CANCELLED","sblr.result_set_pass.cancelled");return r;}if(!journal(c,'C',d)){r.diagnostic=D("RESULT_SET.PASS_FAILED","sblr.result_set_pass.consume_failed");return r;}used[k]=d;live.erase(it);r.ok=true;r.descriptor=d;r.diagnostic=D("OK","ok");return r;}
EngineApiDiagnostic RecoverSblrResultSetPassDescriptors(const EngineRequestContext&c){std::lock_guard lock(mutex_);if(!tagged(c,"right:SBLR_RESULT_SET_ADMIN"))return D("SECURITY.ACCESS_DENIED","sblr.result_set_pass.recovery_denied");for(auto&[unused,d]:live){(void)unused;journal(c,'X',d);}live.clear();return D("OK","ok");}
}
